#!/usr/bin/env node

const crypto = require("node:crypto");
const fs = require("node:fs");
const path = require("node:path");
const sharp = require("sharp");

const root = path.resolve(__dirname, "..");
const checkedAt = "2026-08-05";
const downloadImages = process.argv.includes("--download");
const featureImagesPath = path.join(root, "data/generated/los-angeles-feature-images.json");
const featureImages = fs.existsSync(featureImagesPath)
  ? JSON.parse(fs.readFileSync(featureImagesPath, "utf8")).places
  : {};
const laparks = "City of Los Angeles Department of Recreation and Parks";
const commons = "Wikimedia Commons";

function slugify(value) { return String(value).toLowerCase().replace(/&/g, " and ").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""); }
function stableUuid(parentId, slug) { const b=crypto.createHash("sha256").update(`auditmap:${parentId}:${slug}`).digest().subarray(0,16); b[6]=(b[6]&15)|64; b[8]=(b[8]&63)|128; const h=b.toString("hex"); return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`; }
function schedule(open, close, closed=[]) { return Object.fromEntries(["sunday","monday","tuesday","wednesday","thursday","friday","saturday"].map(day=>[day,closed.includes(day)?[]:[[open,close]]])); }
function photo(slug,url,source,author,license) { return {slug,url,source,author,license}; }
function cm(slug,file,author,license) { const encoded=encodeURIComponent(file.replaceAll(" ","_")).replaceAll("%2F","/"); return photo(slug,`https://commons.wikimedia.org/wiki/Special:Redirect/file/${encoded}?width=1920`,`https://commons.wikimedia.org/wiki/File:${encoded}`,author,license); }

const source = {
  griffith:"https://www2.laparks.org/griffithpark/planyourtrip",
  elysian:"https://www2.laparks.org/park/elysian",
  expo:"https://expositionpark.ca.gov/about-us/faqs/",
  grand:"https://grandparkla.org/visit-park-map/",
  echo:"https://recreation.parks.lacity.gov/aquatic/lake/echo-park-lake",
  venice:"https://www.laparks.org/venice",
  runyon:"https://www2.laparks.org/runyon/",
  lashp:"https://www.parks.ca.gov/?page_id=22272",
  hahn:"https://parks.lacounty.gov/kenneth-hahn-state-recreation-area/",
};

const parks = [
  {id:"launch-ca-los-angeles-griffith-park",name:"Griffith Park",lat:34.1366,lon:-118.2942,address:"4730 Crystal Springs Drive, Los Angeles, CA 90027",source:source.griffith,sourceLabel:laparks,tier:"anchor",hours:"The park is generally open daily 5 a.m.-10:30 p.m. Griffith Observatory, the zoo, museums, golf, trains, concessions, and event venues use separate schedules.",hoursSchedule:schedule("05:00","22:30"),summary:"Los Angeles' vast urban wilderness, combining mountain trails and skyline views with Griffith Observatory, the LA Zoo, museums, playgrounds, trains, picnic areas, and major venues.",arrival:"Pick a named destination before navigating. Crystal Springs serves the zoo, museums, trains, and many family areas; Observatory Road and Vermont Canyon serve the Observatory, Greek Theatre, and central trails.",parking:"Parking is distributed throughout the park. Observatory-area parking is paid during posted hours and fills early; free Greek Theatre parking may be available on non-show days. Event closures can change every normal route.",restrooms:"Restrooms are available at major attractions, developed picnic areas, the Observatory, museums, playgrounds, and selected trailheads, but remote trails have none.",cost:"General park and trail access is free. The Observatory building is free; parking, planetarium shows, zoo admission, museums, rides, golf, food, and events have separate prices.",accessibility:"Developed attractions provide accessible routes and spaces, but steep grades, unpaved trails, distance, and event traffic vary sharply. Navigate to the exact attraction rather than the park center.",dogs:"Leashed dogs are allowed on many park roads and trails, but not inside the zoo, museums, playgrounds, or other posted facilities. Carry water and watch paws in heat.",family:"For younger children, cluster Travel Town, the zoo, Shane's Inspiration, and the merry-go-round area. Observatory and mountain-trail visits are a separate outing because driving and walking distances are substantial.",transit:"The DASH Observatory shuttle runs from Vermont/Sunset to the Observatory daily, generally every 15-20 minutes. Metro buses serve Zoo Drive and Los Feliz approaches, but many destinations still require walking.",need:"Griffith Park is not one compact attraction. Heat, fire danger, trail closures, concerts, and Observatory traffic can change access. Choose no more than two nearby destinations for a relaxed half-day.",photos:[cm("mount-hollywood-view","View of Los Angeles from Mount Hollywood in Griffith Park, Los Angeles, in 2017.jpg","Ackatsis","CC BY-SA 4.0"),cm("griffith-observatory-view","View of Los Angeles from Griffith Observatory.jpg","Andy Gnias","CC BY-SA 4.0"),cm("park-hills","View of Griffith Park from Sunset Boulevard.jpg","Downtowngal","CC BY-SA 4.0"),cm("trail-tree-view","View of tree and Los Angeles from Mount Hollywood in Griffith Park in 2017.jpg","Ackatsis","CC BY-SA 4.0")]},
  {id:"launch-ca-los-angeles-elysian-park",name:"Elysian Park",lat:34.0823,lon:-118.2387,address:"929 Academy Road, Los Angeles, CA 90012",source:source.elysian,sourceLabel:laparks,tier:"supporting",hours:"Open daily from sunrise to sunset. Lodges, athletic fields, restrooms, and reserved areas use their own posted schedules.",hoursSchedule:false,summary:"A large, hilly park above Downtown and Dodger Stadium with skyline overlooks, eucalyptus groves, picnic areas, trails, a disc-golf course, and the Chavez Ravine Arboretum.",arrival:"Angel's Point, the arboretum, Academy Road, and the disc-golf area are separated by hills and roads. Select the named stop instead of the broad park pin.",parking:"Free roadside and small-lot parking is spread through the park. Dodger games, road closures, and large picnics can make normal access unreliable; read every temporary sign.",restrooms:"Restrooms are concentrated around developed picnic and recreation areas and may not be open at every overlook or trail segment.",cost:"General park, trail, arboretum, picnic, and overlook access is free. Reservations and special programs can charge.",accessibility:"Road-accessible overlooks and picnic zones are the easiest choices. Trail grades, uneven surfaces, older facilities, and curb transitions vary.",dogs:"Leashed dogs are allowed in general park areas under posted rules. The park is not a continuous off-leash area.",family:"The arboretum, grassy picnic areas, and short overlook visits work well for families; steep roads and limited barriers at viewpoints require close supervision.",transit:"Bus service reaches edges near Sunset, Stadium Way, and Chinatown, but internal hills make the final walk strenuous. Rideshare drop-off should use a named destination.",need:"Dodger Stadium traffic can reshape the entire area. Visit outside game arrival and departure windows when possible, and do not leave valuables visible in a parked vehicle.",photos:[cm("elysian-view","Elysian Park, Los Angeles, Ca.jpg","Fizzy+lifting","CC BY-SA 3.0"),cm("elysian-landscape","Elysian park.JPG","Daniel E. Romero","CC BY-SA 3.0"),cm("leo-politi","Montecillo de Leo Politi, Elysian Park, Los Angeles.jpg","Jengod","CC BY-SA 4.0")]},
  {id:"launch-ca-los-angeles-exposition-park",name:"Exposition Park",lat:34.0166,lon:-118.2863,address:"700 Exposition Park Drive, Los Angeles, CA 90037",source:source.expo,sourceLabel:"State of California Exposition Park",tier:"anchor",hours:"The park grounds are generally open 8 a.m.-10 p.m., subject to event changes. Museums, the Rose Garden, stadiums, food, and parking facilities keep separate hours.",hoursSchedule:schedule("08:00","22:00"),summary:"A 160-acre cultural campus with the free Rose Garden, California Science Center, Natural History Museum, California African American Museum, stadiums, lawns, and transit access.",arrival:"Use the Expo Park/USC station or choose the museum, Rose Garden, EXPO Center, Coliseum, or stadium entrance before navigating; event security can divide the campus.",parking:"Primary paid entrances are at 39th/Figueroa and Martin Luther King Jr./Hoover. Event rates and closures can be substantial, so Metro E Line is often the simplest option.",restrooms:"Restrooms are available inside museums during admission hours and at selected park facilities. Do not assume a museum restroom is available before opening or during ticketed events.",cost:"Park grounds and Rose Garden are free. The Science Center and CAAM offer free general admission but may require reservations; special exhibits, NHM, parking, and events charge.",accessibility:"Paved campus routes and museum entrances are accessible, but long distances, event fencing, crowds, and construction can change the practical route.",dogs:"Leashed dogs may use general outdoor areas where posted, but pets are not admitted to museums, gardens, stadiums, or event zones except qualified service animals.",family:"The Science Center, Natural History Museum, Rose Garden, and lawns form a strong family day, but one museum plus the garden is usually more comfortable than trying to cover everything.",transit:"Metro E Line's Expo Park/USC station is immediately north of the Rose Garden. Multiple buses serve Figueroa, Vermont, and Martin Luther King Jr. Boulevard.",need:"Always check the event calendar. USC games, stadium concerts, festivals, and construction can change parking prices, security, entrances, and pedestrian routes across the whole campus.",photos:[cm("rose-garden","Exposition Park Rose Garden (Los Angeles).JPG","Los Angeles","CC BY-SA 3.0"),cm("expo-entrance","Los angeles expo park entrance.jpg","Richard H. Kim","CC BY 3.0"),cm("expo-park","Exposition Park - February 2024 - Sarah Stierch.jpg","Sarah Stierch","CC BY 4.0")]},
  {id:"launch-ca-los-angeles-gloria-molina-grand-park",name:"Gloria Molina Grand Park",lat:34.0552,lon:-118.2455,address:"200 N. Grand Avenue, Los Angeles, CA 90012",source:source.grand,sourceLabel:"Gloria Molina Grand Park / The Music Center",tier:"anchor",hours:"Open daily 5:30 a.m.-10 p.m. The playground is posted 8 a.m.-8 p.m.; splash pad, dog run, cafe, restrooms, and events may close independently.",hoursSchedule:schedule("05:30","22:00"),summary:"A four-block civic park between The Music Center and City Hall with the Arthur J. Will Memorial Fountain splash pad, lawns, playground, dog run, events, and Metro access.",arrival:"Grand Avenue is the fountain end; Broadway and Spring Street are closer to the event lawn and City Hall. The park descends across several blocks with elevators and ramps at selected crossings.",parking:"Paid garages surround the park. Lot 10 on Broadway is listed for weekend parking; weekday government business and major events can sharply affect availability.",restrooms:"Public restrooms are marked on the official map near the fountain and central park areas; event layouts and operating conditions can affect access.",cost:"Park access, splash-pad play, lawns, playground, and many public programs are free. Parking, food, and selected events cost extra.",accessibility:"Elevators, ramps, and accessible routes connect the terraced blocks, but not every shortest route avoids stairs. Use the official map when approaching with wheels.",dogs:"Leashed dogs are welcome in general areas, and a small designated dog run is provided. Dogs are not permitted in the splash pad or playground.",family:"The fountain splash pad and playground make this a useful downtown family stop. Bring water shoes and dry clothes, and confirm splash-pad status before promising water play.",transit:"Civic Center/Grand Park Metro station is near the Broadway end; buses serve Grand, Hill, Broadway, Temple, and First. The steep four-block layout matters when choosing your stop.",need:"The splash pad is currently listed open, but fountain maintenance and major civic events can close it with little notice. Check the park FAQ and event calendar on the day of visit.",photos:[cm("fountain","Los Angeles Grand Park Fountain 4.jpg","Al Pavangkanan","CC BY 2.0"),photo("playground","https://grandparkla.org/wp-content/uploads/2022/02/Playground_2-scaled.jpg",source.grand,"Gloria Molina Grand Park / The Music Center","Official park photograph; source attribution retained"),photo("community-lawn","https://grandparkla.org/wp-content/uploads/2025/08/041523_GrandParkEasyMornings_-79-small-scaled.jpg",source.grand,"Gloria Molina Grand Park / The Music Center","Official park program photograph; source attribution retained")]},
  {id:"launch-ca-los-angeles-echo-park-lake",name:"Echo Park Lake",lat:34.0727,lon:-118.2606,address:"751 Echo Park Avenue, Los Angeles, CA 90026",source:source.echo,sourceLabel:laparks,tier:"anchor",hours:"The outdoor lake park generally follows city park hours, 5 a.m.-10:30 p.m. Pedal boats, the boathouse cafe, restrooms, and special events use separate schedules.",hoursSchedule:schedule("05:00","22:30"),summary:"A compact urban lake with a skyline loop, lotus beds, fountain, picnic lawns, wildlife, pedal boats, a boathouse cafe, and easy stroller-friendly walking.",arrival:"The boathouse and boat dock are on the west side near Echo Park Avenue. The loop has gates around the perimeter; choose the west side for rentals and the south side for classic skyline views.",parking:"There is no large dedicated visitor garage. Use legal curb parking around the lake, read time and street-cleaning signs carefully, or arrive by bus; weekends can require several blocks of walking.",restrooms:"A multi-stall public restroom is on Park Avenue, and the boathouse has facilities tied to concession operations. Hours and maintenance can vary.",cost:"Walking, lawns, lotus viewing, and picnicking are free. Pedal boats and boathouse food cost extra; picnic permits may apply for organized use.",accessibility:"The paved lake loop is generally stroller- and wheelchair-friendly, with mostly gentle grades. Gate, curb, crowd, and restroom conditions can still vary.",dogs:"Leashed dogs are allowed on the perimeter paths and lawns under posted rules. Keep them out of the lake and away from nesting birds and dense waterfowl groups.",family:"The loop, fountain, ducks, lotus beds, and swan boats are highly visual for children. Stay between young children and the lake edge, and do not feed wildlife.",transit:"Frequent buses serve Sunset Boulevard and Echo Park Avenue. From Sunset, expect an uphill or downhill approach depending on the stop.",need:"Fishing and swimming are not permitted. Lotus bloom is seasonal, rentals can close for weather or private events, and shade is uneven around the loop.",photos:[cm("skyline","Echo Park Lake with Downtown Los Angeles Skyline.jpg","Adoramassey","CC BY-SA 4.0"),cm("lake-fountain","Echo Park Lake Fountain.jpg","Accord14","CC BY-SA 4.0"),cm("lake-view","Echo Park Lake - Los Angeles, California.jpg","Ramsey Isler","CC BY-SA 4.0")]},
  {id:"launch-ca-los-angeles-venice-beach-ocean-front-walk",name:"Venice Beach & Ocean Front Walk",lat:33.9850,lon:-118.4695,address:"1800 Ocean Front Walk, Venice, CA 90291",source:source.venice,sourceLabel:laparks,tier:"anchor",hours:"The outdoor beach recreation area generally follows posted city beach and park hours. The recreation office is open Monday-Friday 8 a.m.-6 p.m. and Saturday 8 a.m.-4 p.m.; Muscle Beach and other facilities differ.",hoursSchedule:false,summary:"A two-mile public beach district combining Ocean Front Walk, Venice Skatepark, Muscle Beach, basketball and handball courts, playgrounds, bike path, pier, sand, art, and street culture.",arrival:"Navigate to the skatepark, Muscle Beach, recreation center, pier, or a named parking lot. Ocean Front Walk is long, and the nearest practical entrance changes by activity.",parking:"City and private paid lots line the beach, with metered and restricted neighborhood streets inland. Summer weekends and sunsets fill early; verify closing time before leaving a car in a beach lot.",restrooms:"Public beach restrooms and outdoor showers are distributed along Ocean Front Walk, including near major recreation areas. Conditions and hours vary by station.",cost:"Beach, boardwalk, skatepark, outdoor courts, pier, and general recreation access are free. Parking, rentals, food, programs, and Muscle Beach weight passes can charge.",accessibility:"Paved Ocean Front Walk and the beach bike path are accessible, with designated beach access and parking at selected locations. Sand access requires the correct mobility route or equipment.",dogs:"Dogs are not allowed on the sand or most beach facilities except service animals; leashed dogs may use permitted boardwalk areas under posted city rules. Check signs at each zone.",family:"Use the quieter playground and beach areas for younger children, and supervise closely around the skatepark, bike path, surf, crowds, and performers. The boardwalk can be intense at peak times.",transit:"Metro and Big Blue Bus routes serve Venice and Main. Rideshare drop-off inland avoids beach-lot queues, but plan the final walk to the exact activity.",need:"The bike path carries fast traffic, swimming safety depends on lifeguard conditions, and boardwalk crowds change quickly. Keep valuables out of sight and choose a clear family meeting point.",photos:[cm("boardwalk","Venice Beach and Boardwalk, Los Angeles - Nov 2005.jpg","Diliff","CC BY-SA 3.0"),cm("skatepark","Venice Beach Skatepark (Unsplash).jpg","Matteo Paganelli","CC0"),cm("ocean-front-walk","The Venice Beach Boardwalk, Los Angeles, United States (Unsplash).jpg","Vladimir Kudinov","CC0")]},
  {id:"launch-ca-los-angeles-runyon-canyon-park",name:"Runyon Canyon Park",lat:34.1053,lon:-118.3488,address:"2000 N. Fuller Avenue, Los Angeles, CA 90046",source:source.runyon,sourceLabel:laparks,tier:"anchor",hours:"Open daily sunrise to sunset. The West Trail is currently closed until further notice due to a recent fire; other posted areas remain open.",hoursSchedule:false,summary:"A steep urban wilderness hike above Hollywood with multiple entrances, skyline overlooks, paved and dirt routes, and designated off-leash dog areas.",arrival:"Fuller Avenue is the busiest south entrance; Vista Street is another lower approach, and Mulholland Drive enters from the top. Routes are not equivalent in grade, parking, or current closure impact.",parking:"There is no dependable public parking lot at the Fuller entrance. Use legal neighborhood street parking, arrive early, or use transit/rideshare without blocking residential access.",restrooms:"There are no public restrooms in Runyon Canyon. Plan a stop before arrival and pack out all waste.",cost:"Park and trail access are free.",accessibility:"Steep grades, dirt, heat, erosion, gates, and the current West Trail closure limit accessibility. The paved route is still strenuous and is not a flat accessible promenade.",dogs:"Dogs may be off leash only inside designated signed areas and must be under control. Leashes are required elsewhere; carry extra water and protect paws from hot ground.",family:"Older children accustomed to steep hikes may enjoy the views. There is little shade, no restroom, exposed edges, and heavy dog use, so it is not an easy stroller or toddler outing.",transit:"Metro buses serve Hollywood Boulevard and nearby north-south streets; the final approach is uphill. Rideshare at Fuller can be congested, so use a safe legal drop-off.",need:"The West Trail closure is active until further notice. Bring more water than expected, avoid midday heat, watch for rattlesnakes, stay on open trails, and leave before sunset.",photos:[cm("mulholland-entrance","Smokey Bear sign at Mulholland entrance to Runyon Canyon Park, Los Angeles, California, USA.png","Jonathan Deamer","CC BY 4.0"),cm("downtown-view","Downtown LA from Runyon Canyon Park.JPG","3Jo7","CC BY-SA 4.0"),cm("south-view","South view from Runyon Canyon.jpg","Downtowngal","CC BY-SA 4.0")]},
  {id:"launch-ca-los-angeles-los-angeles-state-historic-park",name:"Los Angeles State Historic Park",lat:34.0662,lon:-118.2345,address:"1245 N. Spring Street, Los Angeles, CA 90012",source:source.lashp,sourceLabel:"California State Parks",tier:"anchor",hours:"Open daily 8 a.m. to sunset. Welcome Center, Cargo Snack Shack, programs, and events use separate schedules.",hoursSchedule:false,summary:"A 32-acre state park beside Chinatown with broad lawns, a mile-long walking route, downtown views, habitat gardens, railroad and Indigenous history, family programs, and Metro access.",arrival:"The main address is 1245 N. Spring Street; the paid lot entrance is at 1501 N. Spring. Chinatown station is adjacent, and Union Station is about one mile away.",parking:"The official lot is $2 per hour up to $8 daily. Free street parking exists nearby, but anti-gridlock restrictions apply from 4-6 p.m.; read every sign.",restrooms:"Accessible public restrooms and drinking water are available in the developed park. Building and program hours may differ from park hours.",cost:"Park entry is free. The official lot costs $2 per hour up to $8 daily; cafe purchases and special permitted activities cost separately.",accessibility:"California State Parks reports that all pathways and restrooms are accessible. Broad lawns and temporary event layouts may have different surface conditions.",dogs:"Leashed dogs are allowed throughout permitted outdoor areas. Bring waste bags and keep pets out of habitat restoration areas.",family:"Open lawns, skyline views, the interpretive play area, trains passing nearby, and a simple loop make this an easy family picnic stop. Shade can be limited.",transit:"Metro A Line's Chinatown station is beside the park. Union Station is roughly one mile away, and protected bike access connects through nearby streets.",need:"The park is an active event venue. Check the official calendar for farmers markets, concerts, filming, and fenced areas, and remember that closing time changes with sunset.",photos:[photo("park-lawn","https://www.parks.ca.gov/pages/22272/images/090-P94346.JPG",source.lashp,"California State Parks","Official California State Parks photograph; source attribution retained"),photo("park-path","https://www.parks.ca.gov/pages/22272/images/090-P94363.JPG",source.lashp,"California State Parks","Official California State Parks photograph; source attribution retained"),photo("park-view","https://www.parks.ca.gov/pages/22272/images/090-P94380.JPG",source.lashp,"California State Parks","Official California State Parks photograph; source attribution retained"),photo("park-garden","https://www.parks.ca.gov/pages/22272/images/090-P94391.JPG",source.lashp,"California State Parks","Official California State Parks photograph; source attribution retained")]},
  {id:"launch-ca-los-angeles-kenneth-hahn-state-recreation-area",name:"Kenneth Hahn State Recreation Area",lat:34.0083,lon:-118.3712,address:"4100 S. La Cienega Boulevard, Los Angeles, CA 90056",source:source.hahn,sourceLabel:"Los Angeles County Parks",tier:"anchor",hours:"The regional park is closed Monday and Tuesday. March 1-October 31 it is open Wednesday-Sunday 6 a.m.-8 p.m.; seasonal winter closing is earlier. Restrooms and offices have shorter hours.",hoursSchedule:schedule("06:00","20:00",["monday","tuesday"]),summary:"A 346-acre hilltop regional park with a fishing lake, Japanese garden, playgrounds, picnic areas, sports, more than seven miles of paths, wildlife habitat, and sweeping city views.",arrival:"Enter from La Cienega Boulevard for the main lake, visitor areas, and internal roads. The park is hilly; use the named lake, playground, garden, or overlook rather than walking from the entrance by default.",parking:"Vehicle entry is currently $10 per day, or $8 for a senior or disabled driver. Weekend and holiday Link shuttle service connects Expo/La Cienega station for 25 cents each way.",restrooms:"Restrooms are distributed around the main lake, picnic, playground, and developed recreation areas. Current summer operations list restroom access approximately 6:30 a.m.-7 p.m.",cost:"Pedestrian access is free. Vehicle entry is $10 daily; qualifying senior or disabled drivers pay $8. Reservations and programs may cost extra.",accessibility:"Developed lake, picnic, restroom, and playground areas have accessible facilities, but steep terrain and long distances make destination-specific parking important.",dogs:"Leashed dogs are allowed in permitted park areas under posted rules. Keep pets away from fishing activity, wildlife, playgrounds, and garden beds.",family:"The lake, multiple play areas, picnic lawns, ducks, waterfalls, and short paths can fill an easy family day. Drive between distant areas rather than assuming a stroller-friendly full-park loop.",transit:"The Link Baldwin Hills Parklands Shuttle runs weekends and holidays about every 20 minutes, 8 a.m.-6 p.m., from Expo/La Cienega station. It is ADA accessible and costs 25 cents each way.",need:"Do not arrive Monday or Tuesday: the regional park is closed. Summer heat and limited shade affect hill trails, and weekend picnics can fill the most convenient lake and playground parking.",photos:[photo("play-area","https://parks.lacounty.gov/wp-content/uploads/2018/06/BR6I8115-600x600.jpg",source.hahn,"Los Angeles County Parks","Official Los Angeles County Parks photograph; source attribution retained"),photo("blue-lagoon","https://parks.lacounty.gov/wp-content/uploads/2018/06/BR6I8168-600x600.jpg",source.hahn,"Los Angeles County Parks","Official Los Angeles County Parks photograph; source attribution retained"),cm("hahn-landscape","Kenneth Hahn State Recreation Area.jpg","Jeremy Miles","CC BY-SA 2.0"),cm("downtown-overlook","Kenneth-Hahn-Baldwin-hills-downtownview.jpg","Jengod","CC BY-SA 4.0")]},
];

