const F=[];
function feature(pi,slug,name,type,lat,lon,src,img,description,arrival,restrooms,need){F.push([pi,slug,name,type,lat,lon,src,img,description,arrival,restrooms,need]);}
feature(0,"griffith-observatory","Griffith Observatory","landmark",34.1184,-118.3004,"https://griffithobservatory.org/visit/", "griffith-observatory-view","Free astronomy landmark with exhibits, telescopes, planetarium shows, terraces, Hollywood Sign views, and one of Los Angeles' strongest sunset panoramas.","Use the Observatory address or DASH stop; it is high above the rest of Griffith Park and not a short walk from the zoo.","Restrooms are inside during building hours and near the grounds under posted operations.","The building is free, planetarium tickets cost extra, and parking is paid during enforcement hours. Sunset and clear weekends are busiest.");
feature(0,"los-angeles-zoo","Los Angeles Zoo","zoo",34.1480,-118.2849,"https://lazoo.org/plan-your-visit/","park-hills","A ticketed 133-acre zoo with animals, botanical collections, play and family spaces, food, rentals, and its own full-day visitor operation.","Enter from Zoo Drive; use the zoo lot rather than another Griffith Park attraction pin.","Restrooms, family facilities, food, and water are available inside after admission.","Admission and operating hours are separate from Griffith Park. Check heat, animal availability, timed programs, and current ticket terms.");
feature(0,"travel-town-museum","Travel Town Museum","museum",34.1544,-118.3073,"https://www.laparks.org/traveltown/","park-hills","A free outdoor rail museum where families can walk among historic locomotives and railcars; the miniature train ride is separately operated.","Use 5200 Zoo Drive and the dedicated free lot.","Restrooms are available during museum operations.","Museum entry is free, but train rides cost extra. Outdoor equipment gets hot and the museum has its own hours.");
feature(0,"shanes-inspiration","Shane's Inspiration Playground","playground",34.1454,-118.2908,"https://shanesinspiration.org/playgrounds/shanes-inspiration/","park-hills","A large inclusive destination playground with imaginative zones and accessible play designed for children of varied abilities.","Navigate directly to Shane's Inspiration near Crystal Springs Drive; dedicated parking is nearby.","Restrooms are available near the developed recreation area, but verify current opening.","Expect high use on weekends. Supervise across multiple zones and bring sun protection; playground access differs from nearby zoo hours.");
feature(0,"old-zoo-picnic-area","Old Zoo Picnic Area","historic_site",34.1345,-118.2892,"https://www2.laparks.org/griffithpark/oldzoo.htm","mount-hollywood-view","A free historic picnic and exploration area built around remnants of the former Los Angeles Zoo, with nearby trails and unusual stone enclosures.","Use the Old Zoo or Merry-Go-Round parking area, not the current LA Zoo entrance.","Restrooms are in the broader developed picnic area and may have limited hours.","The old enclosures are not a staffed museum. Watch children on concrete, steps, and uneven ground and avoid closed structures.");
feature(0,"mount-hollywood-trails","Mount Hollywood Trails","trail",34.1280,-118.3013,source.griffith,"mount-hollywood-view","A network of exposed dirt roads and trails climbing to broad city, Observatory, and basin views; route length depends heavily on trailhead.","Choose Observatory, Fern Dell, or another official trailhead before routing; the park-center pin is not a trailhead.","No dependable restroom exists once on the mountain; use facilities before climbing.","No shade, steep grades, heat, fire danger, and closures are serious. Carry water and leave enough daylight to descend.");
feature(0,"autry-museum","Autry Museum of the American West","museum",34.1482,-118.2814,"https://theautry.org/visit","park-hills","A museum of the American West with art, history, Indigenous perspectives, family programs, gardens, food, and a dedicated entrance near the zoo.","Use 4700 Western Heritage Way and the Autry/LA Zoo parking area.","Accessible restrooms and visitor services are inside during admission hours.","The museum is ticketed and closed on selected weekdays; confirm exhibits, hours, and food service before pairing it with the zoo.");
feature(1,"angels-point","Angel's Point","overlook",34.0888,-118.2424,source.elysian,"elysian-view","A hilltop public-art overlook known for the Peter Shire sculpture and wide Downtown, freeway, and Dodger Stadium views.","Approach by Park Row Drive and use nearby legal roadside spaces; the final approach can be confusing.","Do not depend on a restroom at the overlook.","Edges, traffic, broken glass, and limited evening activity warrant extra care. Visit in daylight and keep valuables out of sight.");
feature(1,"chavez-ravine-arboretum","Chavez Ravine Arboretum","garden",34.0787,-118.2474,"https://www.laparks.org/horticulture/arboretum","elysian-landscape","A historic free arboretum within Elysian Park containing mature trees from around the world and a quieter walking landscape.","Use the Academy Road/Elysian Park area and follow arboretum signs; it is not at the Dodger Stadium gates.","Restrooms are in nearby developed park areas, not continuously along the arboretum route.","Tree labels and paths can be subtle. Bring water, expect slopes, and avoid game traffic windows.");
feature(1,"chavez-ridge-disc-golf","Chavez Ridge Disc Golf Course","disc_golf",34.0774,-118.2377,source.elysian,"leo-politi","A rugged free disc-golf course on steep terrain with city views and technically demanding elevation changes.","Use the course-specific Academy Road approach and confirm the current first tee.","No dependable restroom is located on the course itself.","This is not a beginner-flat course: discs can travel into brush and steep slopes. Wear traction, carry water, and yield to other park users.");
feature(2,"exposition-park-rose-garden","Exposition Park Rose Garden","garden",34.0172,-118.2864,"https://www.laparks.org/park/exposition-rose-garden","rose-garden","A free seven-acre formal garden and fountain space between the museums, popular for picnics, portraits, and a quiet break between attractions.","The Metro station and museum entrances open directly toward the garden; use Exposition Boulevard for the shortest transit approach.","Use museum or park facilities during their posted hours; do not assume a restroom inside the garden.","Open dawn to dusk and typically closed for annual maintenance in winter. Event and photography rules may apply.");
feature(2,"california-science-center","California Science Center","museum",34.0158,-118.2863,"https://californiasciencecenter.org/visit","expo-entrance","A major family science museum with free general admission, hands-on galleries, ecosystems, air and space exhibits, IMAX, and special ticketed experiences.","Use the Science Center entrance south of the Rose Garden; reserve timed entry when required.","Restrooms, food, elevators, and family services are available inside.","General admission is free but reservations, IMAX, special exhibitions, and parking can cost. The new Air and Space Center is planned for late 2026, not open yet.");
feature(2,"natural-history-museum","Natural History Museum of Los Angeles County","museum",34.0170,-118.2888,"https://nhm.org/plan-your-visit","expo-park","A ticketed natural-history museum with dinosaurs, mammals, gems, cultural collections, seasonal butterfly and spider pavilions, and family programming.","The main entrance is west of the Rose Garden; use NHM-specific signs from the parking areas or Metro.","Accessible restrooms, food, elevators, and family facilities are inside.","Buy or reserve tickets before busy weekends. Seasonal pavilions and special exhibitions can sell separately from general admission.");
feature(2,"california-african-american-museum","California African American Museum","museum",34.0150,-118.2836,"https://caamuseum.org/visit","expo-entrance","A free museum of African American art, history, and culture with rotating exhibitions and public programs beside the Science Center.","Approach from the east side of the Science Center complex and follow CAAM signs.","Accessible restrooms are available inside during museum hours.","Admission is free, but hours and exhibit closures differ from the park. Confirm the museum calendar before making it the only destination.");
feature(3,"arthur-j-will-fountain-splash-pad","Arthur J. Will Memorial Fountain & Splash Pad","splash_pad",34.0564,-118.2482,"https://grandparkla.org/faq/","fountain","A free interactive water-play area at the Grand Avenue end, below the restored memorial fountain and close to Music Center views.","Enter from Grand Avenue; this is the western, uphill end of the four-block park.","Public restrooms are marked nearby on the official park map.","The splash pad is currently listed open but can close for maintenance or events. Upper fountain pools are off limits; bring water shoes and dry clothes.");
feature(3,"grand-park-playground","Grand Park Playground","playground",34.0549,-118.2443,source.grand,"playground","A compact free playground in the central blocks, useful for a short play break between downtown civic destinations.","Use Hill Street or the central park blocks rather than entering at the far fountain end.","Restrooms are shown nearby on the official map but event access can vary.","Posted playground hours are 8 a.m.-8 p.m. Keep children close at adjacent streets and during crowded events.");
feature(3,"event-lawn-dog-run","Event Lawn & Dog Run","lawn",34.0545,-118.2422,source.grand,"community-lawn","The Broadway end combines the broad event lawn, City Hall views, and a small fenced dog run.","Enter from Broadway or Spring Street for the shortest route.","Restrooms are available elsewhere within the park during operating conditions.","Major events can fence or close the lawn. Dogs must remain leashed outside the designated run and are not allowed in playground or splash areas.");
feature(4,"lake-loop-lotus-beds","Lake Loop & Lotus Beds","trail",34.0727,-118.2606,source.echo,"skyline","A mostly level paved loop around the lake with Downtown views, wetlands, lotus beds, lawns, birds, and repeated entry gates.","Use the south side for the classic skyline composition and the west side for boats and the cafe.","A public restroom is on Park Avenue; availability should be checked on arrival.","The lotus bloom is seasonal, shade is uneven, and wildlife should not be fed. Keep children behind the lake edge.");
feature(4,"echo-park-pedal-boats","Echo Park Pedal Boats","boat_rental",34.0723,-118.2609,"https://wheelfunrentals.com/ca/los-angeles/echo-park/","lake-fountain","A concession offering swan-shaped pedal boats from the historic boathouse dock, including popular evening rides when scheduled.","Go to the west-side boathouse on Echo Park Avenue; reservations and walk-up availability are handled by the operator.","Boathouse facilities are available under concession operating conditions.","Rentals cost extra and may stop for weather, events, water conditions, or capacity. Check current hours and waiver rules directly.");
feature(4,"echo-park-boathouse-cafe","Echo Park Boathouse Cafe","cafe",34.0722,-118.2608,source.echo,"lake-view","A small lakefront concession for drinks and food beside the pedal-boat dock and primary west-side gathering area.","Use the Echo Park Avenue side and look for the boathouse tower.","The boathouse includes restroom facilities, but public access can depend on current operations.","Cafe hours are not the same as park hours and can change. Bring a backup snack and water if the concession is important to the visit.");
feature(5,"venice-skatepark","Venice Skatepark","skatepark",33.9858,-118.4730,"https://www.laparks.org/skatepark/venice","skatepark","A free oceanfront concrete skatepark with bowls and street elements, as visually compelling for spectators as it is demanding for skaters.","Enter Ocean Front Walk near Windward Avenue and follow the beach path to the concrete bowls.","Public beach restrooms are nearby along Ocean Front Walk.","Helmets and protective gear are strongly advised. Keep non-skaters and small children outside the active riding area.");
feature(5,"muscle-beach-venice","Muscle Beach Venice","fitness",33.9850,-118.4720,"https://www.laparks.org/venice/muscle-beach-venice","boardwalk","The historic outdoor weight pen and gymnastic fitness area on Ocean Front Walk, surrounded by basketball, handball, and beach recreation.","Use the recreation center area around 1800 Ocean Front Walk, south of Windward Avenue.","Public restrooms and showers are distributed nearby.","Spectating is free; using weight equipment may require a pass. Seasonal hours are generally 8 a.m.-5 p.m. October-April and 8 a.m.-6 p.m. May-September.");
feature(5,"venice-pier-playgrounds","Venice Pier & Beach Playgrounds","playground",33.9781,-118.4696,source.venice,"ocean-front-walk","The public pier, sand, and multiple playground areas offer a calmer family counterpoint to the busiest boardwalk blocks.","The pier is at Washington Boulevard; playgrounds are spread along Ocean Front Walk, so select the nearest one before parking.","Beach restrooms and outdoor showers are available at selected stations.","Pier access can close for surf or maintenance. Watch bike-path crossings, currents, hot equipment, and the distance back to a parked car.");
feature(6,"fuller-avenue-entrance","Fuller Avenue Entrance","trailhead",34.1011,-118.3509,source.runyon,"south-view","The busiest lower trailhead, offering a direct uphill start from Hollywood but no dedicated visitor lot or restroom.","Use 2000 N. Fuller Avenue and arrive without blocking driveways or red curbs.","There are no restrooms.","Expect immediate climbing, crowds, dogs, and scarce legal parking. The current West Trail closure changes normal loop options.");
feature(6,"mulholland-drive-entrance","Mulholland Drive Entrance","trailhead",34.1114,-118.3495,source.runyon,"south-view","The upper entrance provides quicker access to high viewpoints but still involves dirt, grades, heat, and limited legal roadside parking.","Use the signed Runyon entrance off Mulholland Drive, not a residential lower gate.","There are no restrooms.","Parking fills early and road shoulders are constrained. Confirm which routes remain open before descending far from the car.");
feature(6,"inspiration-point-off-leash-area","Inspiration Point & Off-Leash Area","overlook",34.1064,-118.3492,source.runyon,"downtown-view","A high-view section near designated dog-use terrain, with broad city panoramas and exposed, dusty trail conditions.","Reach it only by an open signed trail from Fuller, Vista, or Mulholland; do not cross closure barriers.","There are no restrooms or water fountains.","Off leash is permitted only in signed areas. Rattlesnakes, heat, steep edges, and fast dogs require attention even on a short visit.");
feature(7,"welcome-center-cargo-snack-shack","Welcome Center & Cargo Snack Shack","visitor_center",34.0674,-118.2339,source.lashp,"park-path","The park's visitor-information and cafe cluster, useful for orientation, programs, snacks, and interpreting the former rail-yard landscape.","Enter near the developed north-central park facilities from North Spring Street.","Accessible restrooms and drinking water are available in the developed park.","Building and cafe hours are shorter than park hours. Confirm before depending on food or staffed interpretation.");
feature(7,"great-lawn-skyline-loop","Great Lawn & Skyline Loop","trail",34.0652,-118.2347,source.lashp,"park-lawn","A broad flexible lawn and approximately mile-long walking route with Downtown views, native planting, event space, and room for casual family recreation.","Either main Spring Street entrance works; the paid lot at 1501 N. Spring is closest to the north end.","Accessible restrooms are available in the developed park, but not at every point on the loop.","Shade is still developing, events can occupy large sections, and closing time follows sunset rather than a fixed evening hour.");
feature(7,"interpretive-play-history-walk","Interpretive Play Area & History Walk","playground",34.0643,-118.2346,source.lashp,"park-garden","A children's exploration area and interpretive landscape connecting Indigenous, agricultural, Chinatown, and railroad history.","Follow park interpretive signs from the central pathways; it is integrated into the landscape rather than a large conventional playground.","Use the accessible park restrooms before extended play.","Play elements may be subtle and sun-exposed. Pair this with the Welcome Center when it is open for stronger context.");
feature(8,"kenneth-hahn-fishing-lake","Kenneth Hahn Fishing Lake","lake",34.0070,-118.3703,source.hahn,"hahn-landscape","A small developed lake with fishing access, ducks, walking paths, lawns, picnic areas, and nearby parking at the heart of the park.","After paying vehicle entry, follow internal signs to the fishing lake and park in the nearest designated lot.","Restrooms are available in the developed lake and picnic area during posted hours.","A valid California fishing license is generally required for anglers 16 and older. Do not feed wildlife; weekend picnic parking fills early.");
feature(8,"blue-lagoon-picnic-area","Blue Lagoon Picnic Area","picnic",34.0089,-118.3691,source.hahn,"blue-lagoon","A named developed picnic area with shelters and internal parking, useful as a concrete meeting point inside the large hilly park.","Follow Blue Lagoon signs after entering from La Cienega; do not stop at the first general park pin.","Use nearby developed-area restrooms during operating hours.","Shelters may be reserved and weekend space fills early. Confirm the exact table or shelter number for group meetups.");
feature(8,"playgrounds-picnic-areas","Playgrounds & Picnic Areas","playground",34.0069,-118.3690,source.hahn,"play-area","Multiple play areas, lawns, shelters, and picnic zones serving different ages and group sizes across the main park roads.","Choose the exact playground or reserved shelter on the county map; the park is too hilly to assume they are adjacent.","Restrooms are near major developed picnic and play zones and close before the overall summer park closing time.","Popular areas fill on weekends. Reservations may control shelters; bring shade and avoid assuming grills or tables are available.");
feature(8,"baldwin-hills-overlook-trails","Baldwin Hills Overlook Trails","overlook",34.0107,-118.3737,source.hahn,"downtown-overlook","Hill paths and overlooks with wide views toward Downtown, the Hollywood Hills, and the Los Angeles Basin.","Drive to the closest upper park area before starting; distances and grades from the lake are greater than they appear.","Do not depend on a restroom at the viewpoint itself.","Trails are exposed and hot. Carry water, watch footing, and distinguish Kenneth Hahn routes from the separate Baldwin Hills Scenic Overlook stair climb.");

feature(0,"greek-theatre","Greek Theatre","event_venue",34.1197,-118.2960,"https://www.lagreektheatre.com/visit","griffith-observatory-view","A historic outdoor amphitheater in Vermont Canyon with concerts, a box office, concessions, and event-specific security and parking operations.","Use 2700 N. Vermont Avenue. On non-show days, nearby parking may support Observatory access; on show days follow the venue's current traffic plan.","Restrooms are available inside for ticketed events; nearby park restroom access varies outside event operations.","The grounds are not a free public attraction during shows. Concert traffic can close roads and eliminate the normal Observatory parking pattern.");

feature(1,"elysian-fields","Elysian Fields","recreation_area",34.0817,-118.2387,source.elysian,"elysian-landscape","A developed recreation zone with two baseball fields, play structures, restrooms, picnic areas, and broad gathering space near Academy Road.","Use the Academy Road recreation-center approach and confirm the exact field or picnic area before meeting a group.","Two restroom areas are identified in the city park plan, but hours and maintenance can vary.","Fields and group picnic areas may be reserved. Dodger traffic and youth sports can fill nearby spaces.");
feature(1,"grace-e-simons-lodge","Grace E. Simons Lodge","lodge",34.0871,-118.2408,"https://www2.laparks.org/special-facilities","elysian-view","A reservable community lodge with indoor gathering space, restrooms, and an adjacent group picnic area high in Elysian Park.","Use 1025 Elysian Park Drive and do not route to the general Academy Road park address.","Interior and exterior restrooms are tied to current lodge and reservation operations.","The lodge and group area can be reserved or closed for private use; confirm access before treating it as a public facility stop.");
feature(1,"solano-canyon-recreation-area","Solano Canyon Recreation Area","recreation_area",34.0739,-118.2374,source.elysian,"leo-politi","A neighborhood-facing recreation area with a practice ball field, tennis courts, play structures, restrooms, and picnic areas.","Approach from Solano Canyon rather than driving across the upper park; game-day street controls may affect access.","A restroom is identified in the city park plan, subject to posted hours and maintenance.","Courts, fields, and group picnic use can be scheduled. Check neighborhood parking restrictions carefully.");
feature(1,"leo-politi-picnic-area","Leo Politi Picnic Area","picnic",34.0860,-118.2480,source.elysian,"leo-politi","A named picnic and recreation area with a practice field, tennis and volleyball courts, and a reservable group picnic zone.","Use the named Leo Politi area and current park signs; it is separate from Angel's Point and the Academy Road recreation center.","Do not rely on a dedicated restroom at this exact picnic area; use a confirmed developed facility first.","The group picnic area may be reserved. Bring shade and confirm court availability before organizing a group visit.");
feature(1,"buena-vista-meadow","Buena Vista Meadow","meadow",34.0845,-118.2347,source.elysian,"elysian-view","An open meadow recreation area with volleyball courts, picnic space, and hillside views within the eastern side of Elysian Park.","Use current Elysian Park signs and a legal roadside space near the meadow rather than crossing closed or event-controlled roads.","Portable facilities may be used here; do not assume a permanent restroom is open.","The older city plan notes a closed play structure. Treat the meadow as picnic and open-space recreation, not a guaranteed playground destination.");

feature(2,"los-angeles-memorial-coliseum","Los Angeles Memorial Coliseum","stadium",34.0141,-118.2879,"https://www.lacoliseum.com/visit/","coliseum-peristyle","The landmark stadium from the 1932 and 1984 Olympics hosts USC football, major events, tours, and future Olympic competition.","Use 3911 S. Figueroa Street and the event-specific gate on the ticket; campus security can make a nearby park entrance unusable.","Restrooms are available inside during ticketed operations, not as general park restrooms.","Entry, tours, bag rules, gates, and parking are event-specific. Large events reshape the entire Exposition Park campus.");
feature(2,"bmo-stadium","BMO Stadium","stadium",34.0135,-118.2851,"https://www.bmostadium.com/plan-your-visit/","expo-park","A soccer and event stadium beside the Coliseum, home to LAFC and Angel City FC with ticketed matches, concerts, food, and security screening.","Use the gate printed on the ticket and check the stadium's transportation notice before entering Exposition Park.","Restrooms are inside during ticketed events.","Bags, entry times, parking, and campus circulation vary by event. Metro is often more predictable than driving.");
feature(2,"expo-center","EXPO Center","recreation_center",34.0147,-118.2895,"https://www.laparks.org/reccenter/expo-center","expo-entrance","A major public recreation complex with an aquatics center, sports, fitness, youth programs, classes, and community services.","Use 3980 Bill Robertson Lane and confirm the specific pool, field, or program entrance before parking.","Accessible restrooms and changing facilities are available during current program operations.","Programs, pool sessions, and facility hours vary. Registration or fees may apply even though the surrounding park is free.");
feature(2,"expo-park-usc-metro-station","Expo Park/USC Metro Station","transit",34.0182,-118.2858,"https://www.metro.net/riding/guide/e-line/","expo-entrance","The E Line station at Exposition Boulevard provides the most direct car-free arrival for the Rose Garden, museums, and north campus.","Exit toward Exposition Park and choose the museum or venue before walking; the stadiums are farther south than the Rose Garden.","Do not depend on a station restroom. Use the first open destination facility.","Train service can be crowded around games and concerts. Load fare before the event and follow temporary crowd-control signs.");

feature(3,"olive-court-cafe","Olive Court & Cafe","cafe",34.0559,-118.2470,source.grand,"grand-park-view","A shaded central court with olive trees, seating, public restrooms, an ATM, and a small cafe or rotating food service near the fountain blocks.","Enter from Grand Avenue or Hill Street and look for Olive Court between the fountain and Performance Lawn.","Public restrooms are located in this western park cluster, subject to current operations.","Cafe and food-truck schedules are shorter than park hours. Bring a backup snack if food is essential.");
feature(3,"performance-lawn","Performance Lawn","lawn",34.0555,-118.2457,source.grand,"community-lawn","A shaded lawn and small stage used for casual lounging, performances, fitness programs, and public events in the western half of the park.","Use Hill Street or Olive Court for the shortest approach.","The nearest public restrooms are in the Olive Court and fountain area.","Programs and event production can close sections or add amplified sound, fencing, and crowd controls.");
feature(3,"community-terrace-flag-garden","Community Terrace & Flag Garden","plaza",34.0550,-118.2436,source.grand,"grand-park-view","A central plaza and garden block connecting the playground side of Grand Park with Broadway-facing lawns and civic views.","Approach from Broadway or Hill Street depending on the final destination; the park slopes across this block.","Use the public restrooms shown on the official park map before crossing to the event lawn.","Temporary markets, ceremonies, and civic events can change routes through the terrace.");
feature(3,"broadway-steps-ada-route","Broadway Steps & Accessible Route","entrance",34.0547,-118.2428,source.grand,"grand-park-view","The Broadway-side stepped seating and accessible route connect the lower civic blocks with the Metro end of the park.","Use Broadway for City Hall, the Event Lawn, dog run, and Metro; use mapped ramps or elevators rather than assuming every stair has an adjacent curb-free path.","Restrooms are elsewhere within the park.","Elevator outages, events, and street closures can alter the easiest mobility route, so check the official map on arrival.");
feature(3,"civic-center-grand-park-metro","Civic Center/Grand Park Metro Station","transit",34.0549,-118.2433,"https://www.metro.net/riding/guide/b-line/","community-lawn","The B and D Line station beside Broadway is the most direct transit entrance for the lower park, playground, dog run, and City Hall end.","Use the Grand Park-facing station exit and remember that the fountain is several uphill blocks away.","Do not rely on a public restroom inside the station; use the park facilities during operating hours.","Escalator or elevator work can change the accessible exit. Major civic events may control the surrounding sidewalks.");

feature(4,"park-avenue-public-restrooms","Park Avenue Public Restrooms","restroom",34.0731,-118.2588,source.echo,"lake-view","The primary multi-stall public restroom serving the lake loop, playground, lawns, and longer family visits.","Use the Park Avenue side of the lake and identify the building before beginning a full loop.","This is the public restroom destination, but maintenance, cleaning, or closure can still affect availability.","Check availability on arrival and keep a backup nearby option in mind during busy festivals.");
feature(4,"echo-park-lake-playground","Echo Park Lake Playground","playground",34.0744,-118.2593,"https://recreation.parks.lacity.gov/reccenter/echo","lake-view","A neighborhood children's play area near the north and east lake lawns, paired naturally with a shorter section of the loop.","Use the north side of the lake rather than the boathouse dock and keep the Park Avenue restroom location in mind.","The Park Avenue public restroom is the practical nearby facility.","Equipment can be hot and shade is uneven. Keep children close because paths, streets, and the lake edge remain nearby.");
feature(4,"lady-of-the-lake-statue","Lady of the Lake Statue","public_art",34.0728,-118.2593,source.echo,"lake-skyline","Ada Mae Sharpless's restored Art Deco sculpture is a recognizable landmark within the lake landscape and a useful orientation point.","Find the statue from the east side of the loop rather than navigating to the boathouse.","Use the Park Avenue restroom before or after this stop.","Viewing is free. Stay on paths and lawns and do not climb the sculpture or enter planted water edges.");
feature(4,"echo-park-lake-bridge","Echo Park Lake Bridge","landmark",34.0735,-118.2600,source.echo,"lake-fountain","A short pedestrian bridge and wetland crossing that breaks up the loop and gives close views of water, lotus beds, birds, and the fountain.","Reach it from the paved loop; wheel users should check the current approach and crowd conditions.","No restroom is on the bridge; use the Park Avenue building.","The bridge can be crowded and wet. Do not feed birds or let children lean beyond protective edges.");
feature(4,"south-lawn-skyline-view","South Lawn Skyline View","overlook",34.0713,-118.2600,source.echo,"skyline","The south side offers the classic lake-and-Downtown composition with open lawn, picnic space, and a direct view toward the fountain.","Enter from the south perimeter for the shortest route to the skyline view; boats and the cafe are on the west side.","The Park Avenue restroom is across the lake loop, not at every lawn entrance.","Shade is limited and lawns can close after rain or for events. Keep valuables attended during photography and picnics.");

feature(5,"venice-basketball-courts","Venice Beach Basketball Courts","basketball",33.9852,-118.4715,source.venice,"recreation-center","Famous free outdoor courts beside Muscle Beach host pickup games, leagues, spectators, and a strong piece of Venice sports culture.","Use the recreation-center area around 1800 Ocean Front Walk and stay clear of the bike path when approaching.","Public beach restrooms and showers are nearby along Ocean Front Walk.","Courts are first-come or programmed unless reserved. Do not enter active play space to take photos.");
feature(5,"venice-handball-pickleball-courts","Venice Handball & Pickleball Courts","court",33.9850,-118.4711,source.venice,"recreation-center","Outdoor handball walls and pickleball courts add free active recreation beside the boardwalk's central sports zone.","Approach through Venice Beach Recreation Center and confirm the specific court before arranging a meetup.","Public beach restrooms are nearby.","Programs, informal queues, wind, sand, and permitted events can affect availability; bring your own equipment.");
feature(5,"venice-recreation-center-stage","Venice Beach Recreation Center & Stage","recreation_center",33.9851,-118.4718,"https://www2.laparks.org/reccenter/venice-beach","recreation-center","The staffed recreation hub manages sports, permits, programs, the outdoor stage, and information for the central Ocean Front Walk facilities.","Use 1800 Ocean Front Walk. The office is not the same as a beach parking entrance.","Public restrooms and showers are distributed nearby; office access follows shorter recreation-center hours.","The office is closed Sundays and city holidays under the current schedule. Events can close or reconfigure outdoor spaces.");
feature(5,"marvin-braude-bike-trail","Marvin Braude Bike Trail","bike_trail",33.9848,-118.4738,"https://beaches.lacounty.gov/la-county-beach-bike-path/","ocean-front-walk","The paved coastal bike path runs through Venice and connects toward Santa Monica and Marina del Rey, carrying fast bicycle and micromobility traffic.","Enter only at a safe paved connection and keep pedestrians out of the travel lane while stopping or taking photos.","Restrooms and water are available at selected beach stations, not continuously along the route.","This is a transportation corridor, not a strolling lane. Look both ways before every crossing and keep children physically close.");
feature(5,"venice-volleyball-courts","Venice Beach Volleyball Courts","volleyball",33.9828,-118.4729,source.venice,"ocean-front-walk","Public sand volleyball courts provide free oceanfront play near the central and southern recreation areas.","Choose the exact court cluster before parking and carry gear across designated path crossings.","Use the nearest open beach restroom and outdoor shower station.","Courts may be informal first-come use or reserved for programs. Wind, hot sand, and tournaments can change availability.");

feature(6,"vista-street-entrance","Vista Street Entrance","trailhead",34.1014,-118.3550,source.runyon,"south-view","A lower neighborhood trailhead west of Fuller that reaches the canyon network without a dedicated public lot or restroom.","Use the official Vista Gate map and verify that the gate and connecting trail are open before relying on this entrance.","There are no restrooms.","The current West Trail closure can affect this approach. Never bypass a closure, block a driveway, or park at a red curb.");
feature(6,"clouds-rest","Clouds Rest Overlook","overlook",34.1074,-118.3500,"https://www.nps.gov/samo/planyourvisit/runyoncanyon.htm","downtown-view","A panoramic east-ridge viewpoint above the canyon reached by a steep open trail from the main fire road network.","Reach it only by currently open signed trails; it is not the Yosemite landmark with the same name.","There are no restrooms or water fountains.","Expect steep steps, exposure, heat, dogs, and loose dirt. The viewpoint is not an accessible roadside overlook.");
feature(6,"indian-rock","Indian Rock","overlook",34.1118,-118.3508,"https://www.nps.gov/samo/planyourvisit/runyoncanyon.htm","runyon-panorama","The park's highest point offers broad views toward both the Los Angeles Basin and San Fernando Valley from the Mulholland side.","Use the Mulholland entrance for the shortest approach, then follow open signed trails; the rock itself requires careful footing.","There are no restrooms.","The final approach is exposed and uneven. Avoid climbing beyond your ability and turn back for heat, wind, fire restrictions, or fading daylight.");
feature(6,"runyon-canyon-road","Runyon Canyon Road","trail",34.1068,-118.3517,source.runyon,"south-view","The broad central fire road forms the most legible north-south spine between lower Hollywood entrances and the Mulholland side.","Choose Fuller, Vista, or Mulholland before routing and use the current official gate map for that approach.","There are no restrooms or dependable drinking fountains.","The road is still steep and exposed. Dogs may be off leash only in signed zones, and emergency or maintenance vehicles retain access.");
feature(6,"east-ridge-trail","East Ridge Trail","trail",34.1068,-118.3491,source.runyon,"downtown-view","A steeper ridge route linking major viewpoints above the canyon with expansive city views and demanding grades.","Enter from a currently open gate and confirm the ridge route on the official map before leaving the central fire road.","There are no restrooms or water fountains.","Heat, eroded steps, loose soil, and exposed edges make this a more demanding option. The West Trail closure does not authorize shortcuts.");

feature(7,"seasonal-wetlands","Seasonal Wetlands","wetland",34.0663,-118.2354,source.lashp,"park-garden","Constructed seasonal wetlands and habitat planting interpret the Los Angeles River basin while capturing water and supporting urban wildlife.","Follow the interior loop and interpretive signs; this is protected habitat rather than a water-play area.","Use the accessible developed-park restrooms before walking the habitat section.","Wetlands change with season and rainfall. Stay on paths, keep dogs leashed, and do not enter planted or muddy areas.");
feature(7,"citrus-grove-promenade","Citrus Grove Promenade","garden",34.0657,-118.2338,"https://www.parks.ca.gov/pages/22272/files/2.0%20project%20description.pdf","park-garden","A linear grove and promenade recalling the site's agricultural history while connecting plazas, paths, shade, and interpretive features.","Use the official park map and connect from the Spring Street entrances or interior loop.","Accessible restrooms are available in the developed park, not necessarily beside the grove.","Fruit and plantings are part of the managed landscape; do not pick produce or leave established paths.");
feature(7,"roundhouse-observation-deck","Roundhouse Observation Deck","overlook",34.0670,-118.2348,"https://www.parks.ca.gov/pages/22272/files/2.0%20project%20description.pdf","park-view","An elevated interpretive feature marks the former Southern Pacific roundhouse and provides context for the rail-yard landscape and skyline.","Follow signs from the interior loop and Welcome Center rather than navigating to a street address.","Use the developed park restroom before the interpretive walk.","The deck and surrounding event areas can close for programs, maintenance, or filming. Respect rail and habitat barriers.");
feature(7,"major-event-lawn","Major Event Lawn","lawn",34.0651,-118.2351,"https://www.parks.ca.gov/NewsRelease/809","park-lawn","A large flexible lawn supports picnics, kite flying, casual recreation, concerts, festivals, markets, and permitted community gatherings.","Use the Spring Street entrance closest to the posted event gate; fencing can divide the normal lawn routes.","Accessible restrooms are in the developed park, with temporary facilities sometimes added for events.","Check the calendar before expecting open lawn. Event production can add noise, security, food vendors, fees, or full closures.");
feature(7,"spring-street-parking-lot","Spring Street Parking Lot & EV Chargers","parking",34.0678,-118.2332,source.lashp,"park-path","The official paid lot at 1501 N. Spring Street provides the clearest vehicle arrival, accessible spaces, permeable paving, and EV charging.","Enter at 1501 N. Spring Street, not the park's 1245 mailing address. Read anti-gridlock and lot-closing signs before leaving the car.","Accessible public restrooms are inside the park, not guaranteed at the parking space itself.","Current posted pricing is $2 per hour up to $8 daily. Event rates, charger availability, and sunset closing can change.");

feature(8,"japanese-garden-loop","Japanese Garden Loop","garden",34.0077,-118.3718,"https://trails.lacounty.gov/Trail/1812/kenneth-hahn-unk2","blue-lagoon","A short landscaped garden loop with a lotus pond, waterfall, bridges, and quiet paths near the park's developed center.","Drive to the closest internal lot and follow garden signs; the hilly park makes walking from the main gate impractical for many visitors.","Use nearby developed-area restrooms during posted hours.","Stay on paths, protect plantings and water, and expect seasonal changes or maintenance closures.");
feature(8,"park-to-playa-trail","Park to Playa Trail","trail",34.0111,-118.3730,"https://trails.lacounty.gov/Trail/1812/kenneth-hahn-unk2","downtown-overlook","The regional trail connection links Kenneth Hahn through the Baldwin Hills toward Culver City and the coast, with hills, overlooks, and multiple jurisdictions.","Use the official county trail map and choose a specific park access point; the full route is much longer than an internal family loop.","Restrooms are available in developed park areas but not continuously along the regional trail.","Carry water, watch closing times, and verify current trail segments before committing to a one-way trip.");
feature(8,"mlk-memorial-tree-grove","Martin Luther King Jr. Memorial Tree Grove","memorial",34.0115,-118.3720,"https://parks.lacounty.gov/memorial-tree-grove-honoring-dr-martin-luther-king-now-open-to-the-public/","downtown-overlook","A hilltop memorial grove creates a reflective landscape among trees and broad city views near the park's upper areas.","Drive or walk to the closest signed upper-park access and leave enough time to return before the seasonal gate closing.","Do not depend on a restroom at the grove; use a developed area first.","The grove is free with park access. Respect memorial plantings and avoid events or restoration barriers.");
feature(8,"olympic-forest-city-view-trail","Olympic Forest & City View Trail","trail",34.0120,-118.3702,"https://trails.lacounty.gov/TrailsList","hahn-landscape","Hilltop trees honoring Los Angeles' Olympic history connect with signed paths and wide views across the basin.","Use the county trail locator and internal park signs; this upper area is not adjacent to the fishing lake despite appearing close on a small map.","There is no dependable restroom at the overlook; use developed facilities before climbing.","Trails are exposed and can be hot. Check current wayfinding, carry water, and return before the park's seasonal closing time.");

function answer(p,key,question,text,src=p.source){return{intentKey:key,question,answer:text,sourceLabel:p.sourceLabel,source:src,verifiedAt:checkedAt,freshnessClass:["hours","parking","weather","need-to-know"].includes(key)?"fast":"slow",status:"verified"};}
function answers(p){return [["hours",`When is ${p.name} open?`,p.hours],["parking",`Where should I park for ${p.name}?`,p.parking],["entrance",`What is the best entrance for ${p.name}?`,p.arrival],["restroom",`Are there restrooms at ${p.name}?`,p.restrooms],["fees",`Is ${p.name} free?`,p.cost],["accessibility",`How accessible is ${p.name}?`,p.accessibility],["dogs",`Are dogs allowed at ${p.name}?`,p.dogs],["family",`Is ${p.name} good for children?`,p.family],["transit",`How do I reach ${p.name} without a car?`,p.transit],["need-to-know",`What should I know before visiting ${p.name}?`,p.need],["weather",`What weather check matters before visiting ${p.name}?`,`Check current heat, air quality, wind, rain, surf where relevant, and operator alerts. Los Angeles heat and fire conditions can affect trails and outdoor facilities even when general park hours remain unchanged.`]].map(([k,q,t])=>answer(p,k,q,t));}
async function download(p,item){const rel=`${slugify(p.name)}/${item.slug}.webp`,out=path.join(root,"assets/parks/los-angeles-super",rel);if(fs.existsSync(out))return`/assets/parks/los-angeles-super/${rel}`;if(!downloadImages)throw new Error(`Missing ${p.name}/${item.slug}; use --download`);let r;for(let i=1;i<=4;i++){r=await fetch(item.url,{redirect:"follow",headers:{"user-agent":"Mozilla/5.0 AuditMap/1.0",accept:"image/*,*/*;q=.8",referer:item.source}});if(r.ok||r.status!==429)break;await new Promise(x=>setTimeout(x,i*1800));}if(!r?.ok)throw new Error(`${p.name}/${item.slug}: ${r?.status}`);fs.mkdirSync(path.dirname(out),{recursive:true});await sharp(Buffer.from(await r.arrayBuffer())).rotate().resize(1600,1000,{fit:"cover",position:"attention",withoutEnlargement:true}).webp({quality:83}).toFile(out);return`/assets/parks/los-angeles-super/${rel}`;}
function makeFeature(p,row,imgs){const[,slug,name,type,lat,lon,src,imgSlug,description,arrival,restrooms,need]=row,id=stableUuid(p.id,slug),base=featureImages[p.id]?.[slug]||imgs.find(x=>x.slug===imgSlug)||imgs[0],pic={...base,featureId:id,latitude:lat,longitude:lon,alt:`${name} at ${p.name}`};const qs=[["location",`Where exactly is ${name}?`,arrival],["parking",`Where should I park for ${name}?`,p.parking],["hours",`When is ${name} open?`,need],["restroom",`Are there restrooms near ${name}?`,restrooms],["fees",`Is ${name} free?`,p.cost],["accessibility",`How accessible is ${name}?`,p.accessibility],["dogs",`Are dogs allowed at ${name}?`,p.dogs],["family",`Is ${name} good for children?`,p.family],["need-to-know",`What should I know before visiting ${name}?`,need]].map(([k,q,t])=>answer(p,k,q,t,src));return{id,slug,name,feature_type:type,description,latitude:lat,longitude:lon,details:{category:type.replaceAll("_"," "),includeInParentGallery:true,positionQuality:"Named destination cross-checked against its cited official source",address:p.address,hours:need,hoursSchedule:false,cost:p.cost,accessibility:p.accessibility,locationContext:arrival,needToKnow:need,informationSourceLabel:p.sourceLabel,informationSourceUrl:src,informationCheckedAt:checkedAt,imageUrl:pic.url,imageSourceUrl:pic.source,imageAuthor:pic.author,imageLicense:pic.license,imageAlt:pic.alt,images:[pic],searchAnswers:qs},source_label:p.sourceLabel,source_url:src,verified_at:checkedAt};}
function ensureRows(){const f=path.join(root,"data/nationwide-major-parks-launch.csv");let lines=fs.readFileSync(f,"utf8").trimEnd().split("\n");for(const p of parks){const prefix=`Pacific,CA,Los Angeles,${p.name},`;const row=`Pacific,CA,Los Angeles,${p.name},${p.tier},yes,super-enriched`;const i=lines.findIndex(x=>x.startsWith(prefix));i>=0?lines[i]=row:lines.push(row);}fs.writeFileSync(f,`${lines.join("\n")}\n`);const lf=path.join(root,"data/launch-location-overrides.json"),rows=JSON.parse(fs.readFileSync(lf,"utf8"));for(const p of parks){const v={id:p.id,park:p.name,city:"Los Angeles",state:"CA",latitude:p.lat,longitude:p.lon,address:p.address,displayName:`${p.name}, Los Angeles, CA`,source:p.sourceLabel,sourceUrl:p.source,checkedAt};const i=rows.findIndex(x=>x.id===p.id);i>=0?rows[i]=v:rows.push(v);}fs.writeFileSync(lf,`${JSON.stringify(rows,null,2)}\n`);}
function upsert(d,p){const i=d.parks.findIndex(x=>x.id===p.id);i>=0?d.parks[i]=p:d.parks.push(p);}
async function main(){ensureRows();const ap=path.join(root,"data/generated/all-subsites-ready.json"),pp=path.join(root,"data/generated/pilot-subsites-ready.json"),cp=path.join(root,"data/parent-park-information-enrichment-national.json"),all=JSON.parse(fs.readFileSync(ap)),pilot=JSON.parse(fs.readFileSync(pp)),campaign=JSON.parse(fs.readFileSync(cp));for(const p of parks){const imgs=[];for(const item of p.photos){const url=await download(p,item);imgs.push({...item,url,alt:`${p.name} in Los Angeles, California`,latitude:p.lat,longitude:p.lon,positionQuality:"Associated with the named destination by its cited source; exact camera position is not published"});}const fsx=F.filter(r=>r[0]===parks.indexOf(p)).map(r=>makeFeature(p,r,imgs)),existing=all.parks.find(x=>x.id===p.id)||{},record={...existing,id:p.id,name:p.name,type:"Park",city:"Los Angeles",state:"CA",country:"US",citySlug:"los-angeles-CA",slug:slugify(p.name),searchCategory:"park",neighborhood:"Los Angeles",status:"Sourced public-access visitor guide",summary:p.summary,searchDescription:`Hours, parking, transit, real images, internal destinations, and essential visitor answers for ${p.name} in Los Angeles.`,address:p.address,latitude:p.lat,longitude:p.lon,hours:p.hours,hoursSchedule:p.hoursSchedule,cost:p.cost,accessibility:p.accessibility,sourceLabel:p.sourceLabel,source:p.source,verifiedAt:checkedAt,operator:p.sourceLabel,image:imgs[0],images:imgs.slice(1),sources:[{label:p.sourceLabel,url:p.source}],launchTier:p.tier,likelySubsites:true,publishStatus:"super-enriched",researchQueue:[],transit:p.transit,searchAnswers:answers(p),features:fsx,amenities:[],comments:existing.comments||[]};upsert(all,record);upsert(pilot,record);campaign.parks[p.id]={operator:p.sourceLabel,sourceLabel:p.sourceLabel,source:p.source,address:p.address,summary:p.summary,hours:p.hours,hoursSchedule:p.hoursSchedule,cost:p.cost,accessibility:p.accessibility,transit:p.transit,searchAnswers:record.searchAnswers,image:imgs[0],additionalImages:imgs.slice(1),verifiedAt:checkedAt};}fs.writeFileSync(ap,`${JSON.stringify(all,null,2)}\n`);fs.writeFileSync(pp,`${JSON.stringify(pilot,null,2)}\n`);fs.writeFileSync(cp,`${JSON.stringify(campaign,null,2)}\n`);console.log(`Super-enriched ${parks.length} Los Angeles guides with ${F.length} focused destinations and ${parks.reduce((n,p)=>n+p.photos.length,0)} sourced photos.`);}
main().catch(e=>{console.error(e.stack||e);process.exitCode=1;});
